    "description": "新华社达喀尔10月24日电（记者陈晨）巴马科消息：马里武装部队总参谋部24日发布公报说，一支联合巡逻队在该国东北部梅纳卡区首府梅纳卡市附近发现54具平民遗体。 公报说，军方接到上述地区平民遭恐怖袭击的消息后，派出该联合巡逻队展开搜寻，在梅纳卡市东南约35公里的一处聚居点发现这些遗体，同时找到9名幸存者。目前，死者已安葬，幸存者被送往梅纳卡市接受救助。公报未说明袭击发生的具体时间。 公报还说，据初步收集的证词，极端组织“大撒哈拉伊斯兰国”…",
    "content": "新华社达喀尔10月24日电（记者陈晨）巴马科消息：马里武装部队总参谋部24日发布公报说，一支联合巡逻队在该国东北部梅纳卡区首府梅纳卡市附近发现54具平民遗体。 公报说，军方接到上述地区平民遭恐怖袭击的消息后，派出该联合巡逻队展开搜寻，在梅纳卡市东南约35公里的一处聚居点发现这些遗体，同时找到9名幸存者。目前，死者已安葬，幸存者被送往梅纳卡市接受救助。公报未说明袭击发生的具体时间。 公报还说，据初步收集的证词，极端组织“大撒哈拉伊斯兰国”涉嫌实施此次袭击。军方已对高风险地区的平民加强保护或实施转移，并表示将追查袭击者…"
