    "title": "葡萄牙多个城市举行示威游行和民众集会",
    "link": "https://m.thepaper.cn/newsDetail_forward_34326618",
    "pub_date": "2026-10-25 01:26:24",
    "author": "",
    "description": "资料图 当地时间10月24日，葡萄牙多个城市继续举行示威游行和民众集会，要求政府采取措施应对住房危机。里斯本、波尔图、科英布拉等葡萄牙主要城市均爆发了大规模示威活动。抗议的民众要求葡萄牙政府采取一系列住房相关措施，例如停止在没有替代方案的情况下强行拆除房屋或驱逐住客，增加公共住房，实施租金上限，以及将空置房产用作住房等。 葡萄牙多地住房相关的抗议活动已经进行了约两周，部分主要城市的居民还计划在广场设立营地，或进行守夜等行动。",
    "content": "资料图 当地时间10月24日，葡萄牙多个城市继续举行示威游行和民众集会，要求政府采取措施应对住房危机。里斯本、波尔图、科英布拉等葡萄牙主要城市均爆发了大规模示威活动。抗议的民众要求葡萄牙政府采取一系列住房相关措施，例如停止在没有替代方案的情况下强行拆除房屋或驱逐住客，增加公共住房，实施租金上限，以及将空置房产用作住房等。 葡萄牙多地住房相关的抗议活动已经进行了约两周，部分主要城市的居民还计划在广场设立营地，或进行守夜等行动。"
