    "description": "10月23日、24日，来自上海的《繁花》三部曲登上“第六届粤港澳大湾区文化艺术节”的舞台，在广东省友谊剧院上演第一季。舞台上，上海风情浓郁的“弄堂史诗”次第展开，特邀的香港舞台剧名家詹瑞文则以粤语参加表演，为全剧注入亲切的粤式风情。沪语话剧穿插粤语乡音，让这部“大湾区”定制版《繁花》收获全新的回响。 作为此次艺术节“艺汇湾区·剧目展演”板块入选剧目，舞台剧《繁花》三部曲将是首度在大湾区开启三季连演，这也是三季故事史无前例首次在同一座城市…",
    "content": "10月23日、24日，来自上海的《繁花》三部曲登上“第六届粤港澳大湾区文化艺术节”的舞台，在广东省友谊剧院上演第一季。舞台上，上海风情浓郁的“弄堂史诗”次第展开，特邀的香港舞台剧名家詹瑞文则以粤语参加表演，为全剧注入亲切的粤式风情。沪语话剧穿插粤语乡音，让这部“大湾区”定制版《繁花》收获全新的回响。 作为此次艺术节“艺汇湾区·剧目展演”板块入选剧目，舞台剧《繁花》三部曲将是首度在大湾区开启三季连演，这也是三季故事史无前例首次在同一座城市完整集结。三周时间内，剧组将在两个剧场接力上演9小时全剧。第一季两场结束之后，《…"
