    "content": "中新社日本名古屋10月25日电 (记者 朱晨曦)第五届亚洲残疾人运动会24日在日本名古屋瑞穗公园田径场闭幕。中国体育代表团获得207枚金牌、117枚银牌和111枚铜牌，共435枚奖牌，连续第五届位居金牌榜、奖牌榜首位，创造境外参加亚残运会最好成绩。"
