    "description": "新华社日内瓦10月24日电 题：在阿尔卑斯山看见武夷山——中瑞山峰结为“姐妹峰” 新华社记者连漪 陈俊侠 在海拔2100多米的瑞士菲斯特峰山顶上，一块展示中国武夷山风光、介绍两地合作的展板23日亮相。武夷山玉女峰与菲斯特峰相关管理机构通过视频连线，同步举行“姐妹峰”揭牌仪式。 雪花飘落，阿尔卑斯群峰在云雾中时隐时现。展板画面里，玉女峰临溪而立，倒映碧水之中，竹筏缓缓前行。展板上的武夷山水与身后的瑞士雪山相映，从九曲溪畔到阿尔卑斯山间，两…",
    "content": "新华社日内瓦10月24日电 题：在阿尔卑斯山看见武夷山——中瑞山峰结为“姐妹峰” 新华社记者连漪 陈俊侠 在海拔2100多米的瑞士菲斯特峰山顶上，一块展示中国武夷山风光、介绍两地合作的展板23日亮相。武夷山玉女峰与菲斯特峰相关管理机构通过视频连线，同步举行“姐妹峰”揭牌仪式。 雪花飘落，阿尔卑斯群峰在云雾中时隐时现。展板画面里，玉女峰临溪而立，倒映碧水之中，竹筏缓缓前行。展板上的武夷山水与身后的瑞士雪山相映，从九曲溪畔到阿尔卑斯山间，两地嘉宾在“云端”共同见证这一时刻。 “我们的目标是激发国际游客对武夷山的兴趣。”…"
