    "description": "新华社郑州10月24日电（记者王烁）天气转凉，不少人喜欢在家做艾灸，暖身驱寒。但艾灸看似简单，方法不对反而可能伤身。 河南中医药大学第一附属医院传统疗法科副主任医师赵计轩提醒，艾灸的温度、时长、选穴以及适用人群都有讲究，并非人人适合。 “艾灸的温度不是越烫越好。”赵计轩表示，有些人认为艾灸时，皮肤越红效果越好，甚至把皮肤起泡当成“排病反应”，这是一个常见误区。赵计轩提醒，艾灸时以身体感觉到温热感为宜，切忌贪热。艾灸烫伤多属于低温烫伤，初…",
    "content": "新华社郑州10月24日电（记者王烁）天气转凉，不少人喜欢在家做艾灸，暖身驱寒。但艾灸看似简单，方法不对反而可能伤身。 河南中医药大学第一附属医院传统疗法科副主任医师赵计轩提醒，艾灸的温度、时长、选穴以及适用人群都有讲究，并非人人适合。 “艾灸的温度不是越烫越好。”赵计轩表示，有些人认为艾灸时，皮肤越红效果越好，甚至把皮肤起泡当成“排病反应”，这是一个常见误区。赵计轩提醒，艾灸时以身体感觉到温热感为宜，切忌贪热。艾灸烫伤多属于低温烫伤，初期可能只有轻微发热发痒，等察觉时可能已经伤及深层组织。皮肤出现水泡、破溃，不是“…"
