    "description": "秋染洞庭，风遇名楼 10月16日 40余名记者齐聚岳阳楼畔 参加“美丽乡村三湘行——第21届海峡两岸媒体记者 来湘联合采访活动” 今年 是范仲淹《岳阳楼记》诞生980周年 不少朋友是第一次登上这座千古名楼 隔着海峡、隔着山水 我们曾在课本里诵读过同一篇《岳阳楼记》 在字句间想象过八百里洞庭的浩渺烟波 憧憬过“先天下之忧而忧 后天下之乐而乐”的家国情怀 此刻并肩站在古楼飞檐之下 在每个人心里激起的触动全然相通 这场跨越山海的文脉相约 既让…",
    "content": "秋染洞庭，风遇名楼 10月16日 40余名记者齐聚岳阳楼畔 参加“美丽乡村三湘行——第21届海峡两岸媒体记者 来湘联合采访活动” 今年 是范仲淹《岳阳楼记》诞生980周年 不少朋友是第一次登上这座千古名楼 隔着海峡、隔着山水 我们曾在课本里诵读过同一篇《岳阳楼记》 在字句间想象过八百里洞庭的浩渺烟波 憧憬过“先天下之忧而忧 后天下之乐而乐”的家国情怀 此刻并肩站在古楼飞檐之下 在每个人心里激起的触动全然相通 这场跨越山海的文脉相约 既让两岸媒体人沉浸式触摸湖湘文化的深厚底蕴 也为两岸人文交流写下了鲜活温暖的一笔 &…"
