    "content": "新华社拉姆安拉10月24日电（记者徐泽宇 赵伟宏）据巴勒斯坦通讯社24日报道，以色列军队自23日开始在约旦河西岸城市希伯伦展开军事行动，将当地约1500名巴勒斯坦人驱离住所，还有2500人将被驱离。 巴勒斯坦通讯社援引希伯伦省省长哈立德·杜丁的话报道，以军行动已致200多个巴勒斯坦家庭流离失所。以军还在当地捣毁住宅和商店，封锁了通往希伯伦的道路，禁止居民进出城市。 以色列国防军23日发表声明称，将在希伯伦开展“精准、定向、全面”的搜查行动，定位并摧毁“恐怖分子”的设施和武器。 以色列媒体23日报道，当天希伯伦附近发…"
