    "content": "新华社东京10月24日电（记者陈泽安 梁晨）日本共同社24日报道称，日本政府为在今年年内修订“安保三文件”，拟从10月底起加强有关安保政策的宣传，并针对不同年龄群体采取差异化宣传。此举在日本引发担忧。 报道称，面向年轻群体，日本政府拟在互联网和社交平台上发布与知名人士合作制作的视频，在东京地铁以及东京涩谷十字路口投放广告，强调安全保障与日常生活息息相关；面向中老年群体，除了社交媒体和电视外，还拟在购物中心投放广告，阐述安全保障与家庭和生活安全之间的联系。 日本政府计划在今年年内修订“安保三文件”，预计“新型作战方式…"
