    "content": "10月24日10时，西藏那曲市索县人民医院急诊楼前，忙碌有序。在地震中肋骨骨折的80岁的老人莫多，躺在担架车上被缓缓抬上救护车，出发赶往拉萨市。 莫多来自巴青县玛如乡格隆改村，这个村是此次地震重灾区之一。22日晚，经过连夜治疗监护，莫多生命体征平稳。出于对老人后续康复的考虑，家属提出转往拉萨市接受进一步治疗的诉求。医院立刻协调、护送莫多前往西藏自治区医院。 10月24日上午，80岁的患者莫多在那曲市索县人民医院被抬上救护车，转院至西藏自治区医院。新华社记者 刘洪明摄 22日22时33分许，西藏那曲市巴青县发生7.0…"
