    "content": "中新社北京10月24日电 (刘梦青)2026赛季中超联赛第29轮比赛24日全部战罢。大连英博以1:0力克领头羊成都蓉城，将双方积分差距缩小至3分，本赛季中超冠军归属悬念延续至最后一轮。武汉三镇本轮3:5不敌山东泰山，提前一轮确认降级。"
