    "description": "中新网香港10月24日电 (记者 张语洽)素色宣纸铺展，毛笔吸足浓墨，只待挥洒。24日，由香港东方书画院与香港立桥人寿保险有限公司联合主办的“中国书法体验活动”在香港举行。活动以“一字藏千载——中国地域古雅简称文化”为主题，香港东方书画院院长、香港狮子山文艺协会会长梁君度以中国34个省级行政区简称为题，结合书法体验教学，带领现场香港青少年儿童解读方块字下的历史典故与地域文化。",
