    "pub_date": "2026-10-24 21:25:11",
    "author": "",
    "description": "中新网北京10月24日电(记者 国璇 朱晨曦) 第五届亚残运会于10月18日至24日在日本爱知县名古屋市举行。由中国残联组建的中国残疾人体育代表团获207枚金牌、117枚银牌、111枚铜牌共计435枚奖牌，连续五届亚残运会位居金牌榜、奖牌榜首位，还刷新了11项世界纪录、18项亚洲纪录，创造境外参赛最好成绩，取得运动成绩和精神文明双丰收。",
