    "description": "新华社科威特城10月24日电（记者尹炣 胡浩东）萨那消息：也门胡塞武装24日说，也门首都萨那和塔伊兹省的红海港口城市穆哈当天遭到猛烈空袭，造成多人死伤。 胡塞武装控制的马西拉电视台24日说，沙特阿拉伯主导的多国联军连续对萨那发动空袭，现场发生剧烈爆炸。当地居民告诉新华社记者，战机持续在萨那上空盘旋，爆炸声不断。 据马西拉电视台报道，萨那西部阿斯尔地区一栋房屋遭空袭，造成3人死亡、多人受伤。另外，位于萨那西北部的哈姆丹区一座水泥厂遭到袭击…",
    "content": "新华社科威特城10月24日电（记者尹炣 胡浩东）萨那消息：也门胡塞武装24日说，也门首都萨那和塔伊兹省的红海港口城市穆哈当天遭到猛烈空袭，造成多人死伤。 胡塞武装控制的马西拉电视台24日说，沙特阿拉伯主导的多国联军连续对萨那发动空袭，现场发生剧烈爆炸。当地居民告诉新华社记者，战机持续在萨那上空盘旋，爆炸声不断。 据马西拉电视台报道，萨那西部阿斯尔地区一栋房屋遭空袭，造成3人死亡、多人受伤。另外，位于萨那西北部的哈姆丹区一座水泥厂遭到袭击，造成人员伤亡。 该电视台还说，24日上午以来，穆哈遭到近20次空袭。穆哈位于塔…"
