    "description": "平陆运河刚通航一个多月，台湾青年邱庆龄就已经到访两次了。在今年的国庆节，他与几位台湾青年一同来到了平陆运河，为祖国母亲献上了一份特殊的生日礼物。近日，他受邀参加第二十二届桂台经贸文化合作论坛，在论坛活动中参观平陆运河。这一次，同样怀着激动的心情，邱庆龄还看到了机遇。 记者：黄凯莹、孙闯 新华社音视频部制作",
    "content": "平陆运河刚通航一个多月，台湾青年邱庆龄就已经到访两次了。在今年的国庆节，他与几位台湾青年一同来到了平陆运河，为祖国母亲献上了一份特殊的生日礼物。近日，他受邀参加第二十二届桂台经贸文化合作论坛，在论坛活动中参观平陆运河。这一次，同样怀着激动的心情，邱庆龄还看到了机遇。 记者：黄凯莹、孙闯 新华社音视频部制作"
