    "content": "新华社石家庄10月24日电（记者赵瀚泽、龚璟璐）来华出席2026全球治理论坛（雄安）的联合国副秘书长盖·莱德24日在河北雄安新区接受记者采访时表示，中国在全球治理中发挥着关键作用，四大全球倡议同联合国目标高度契合。中国面向未来的前瞻性眼光令人印象深刻，这正是国际社会所需要的。 莱德表示，联合国始终将中国视为坚定的合作伙伴。他说，中国提出的四大全球倡议涉及发展、安全、文明、治理等领域，同联合国等多边体系关注的议题和目标高度契合。“中国多次表达了对多边主义和联合国的坚定支持，表示要维护以联合国为核心的国际体系、以国际法…"
