    "content": "新华社北京10月24日电（记者周圆）当前多媒体技术正处于代际跃迁的关键时期，标准化的战略价值更加突出。记者从日前在杭州举行的多媒体国际标准高级别研讨会上了解到，中国将坚持务实协同创新，当好依托标准赋能全球技术进步的积极贡献者，推动中国技术服务全球共同发展。 标准是全球技术互通的通用语言，是实现互联互通、促进公平贸易、驱动技术革新与产业升级的重要基石。当前，中国在音视频编码、AI原生媒体编码、沉浸式媒体等重点方向持续输出成果、发挥建设性作用。 工业和信息化部相关负责人在会上说，面对新一轮科技革命和产业变革的重大历史机…"
