    "content": "治国必先治党，党兴才能国强。 以习近平党建思想为指引，将全面从严治党进行到底，新时代的中国共产党人必将团结带领全国各族人民，在新征程上书写强国建设、民族复兴伟业新篇章。 统筹：吴炜玲 编导：刘在 记者：杨青 海报：刘烜硕 新华社音视频部制作"
