    "category": "新闻",
    "title": "刘奇凡任中共云南省委副书记、省政府党组书记",
    "link": "https://www.zaobao.com/news/china/story20261024-9889277",
    "pub_date": "2026-10-24 19:38:12",
    "author": "",
    "description": "中共青海省委副书记刘奇凡履新云南省委副书记、省政府党组书记。 据“云南发布”微信公众号星期六（10月24日）消息，中共中央批准刘奇凡任云南省委委员、常委、副书记。云南省委也决定，刘奇凡任云南省政府党组书记。 公开资料显示，现年59岁的刘奇凡曾任贵州省委常委、秘书长，内蒙古自治区党委常委、纪委书记、自治区监委主任，辽宁省委常委、省纪委书记、省监委主任等职。 2023年12月，刘奇凡任青海省委副书记，直至此次履新。",
    "content": "中共青海省委副书记刘奇凡履新云南省委副书记、省政府党组书记。 据“云南发布”微信公众号星期六（10月24日）消息，中共中央批准刘奇凡任云南省委委员、常委、副书记。云南省委也决定，刘奇凡任云南省政府党组书记。 公开资料显示，现年59岁的刘奇凡曾任贵州省委常委、秘书长，内蒙古自治区党委常委、纪委书记、自治区监委主任，辽宁省委常委、省纪委书记、省监委主任等职。 2023年12月，刘奇凡任青海省委副书记，直至此次履新。"
