    "description": "巴青震中，平均海拔接近4800米。高原旷野里，远处山峰覆盖着薄薄的积雪，风吹过，涌起刺骨寒意。 冷，是地震发生后灾区群众的感受。 暖，是记者连日耳闻目睹的真情。 10月24日拍摄的巴青县玛如乡扎若改村安置点（无人机照片）。新华社记者丁增尼达 摄 一团炉火 22日22时33分，一场突然而至的天灾打破了西藏高原深处的静谧。7.0级的地震中，地动山摇、乱石滚落、土墙倾颓。 行走在震中，夜色裹着刀子似的寒风，顺着衣领、袖口往骨缝里钻，指尖不消片…",
