    "description": "山东省枣庄市峄城区的果农们近日完成了石榴采收。 “这几年，我们主要种植‘秋艳’，鲜果市场价能卖到每斤8元左右。不少人预订‘秋艳’石榴苗，每年光育苗的纯利润就有十几万元。”峄城区榴园镇王府山村果农李永水说。 果农在采摘石榴。（受访者供图） 枣庄市石榴研究院副院长毕润霞告诉记者，李永水种植的“秋艳”，是目前唯一的国审石榴良种，具有丰产、稳产、籽粒大、出汁率高、耐储存等优点。“秋艳”培育成功后，枣庄在当地推广种植。2015年底，石榴研究院把两…",
    "content": "山东省枣庄市峄城区的果农们近日完成了石榴采收。 “这几年，我们主要种植‘秋艳’，鲜果市场价能卖到每斤8元左右。不少人预订‘秋艳’石榴苗，每年光育苗的纯利润就有十几万元。”峄城区榴园镇王府山村果农李永水说。 果农在采摘石榴。（受访者供图） 枣庄市石榴研究院副院长毕润霞告诉记者，李永水种植的“秋艳”，是目前唯一的国审石榴良种，具有丰产、稳产、籽粒大、出汁率高、耐储存等优点。“秋艳”培育成功后，枣庄在当地推广种植。2015年底，石榴研究院把两万多株“秋艳”石榴苗无偿提供给了果农。 2025年，枣庄市新栽植石榴53万株，其…"
