    "content": "新华社北京10月24日电 2027年度中央机关公开遴选和公开选调公务员报名即将开始，考生可于10月28日8:00至11月6日18:00期间，登录“2027年度中央机关公开遴选和公开选调公务员专题网站”（http://subb.scs.gov.cn/lx2027）进行网上报名，笔试将于11月28日在全国各直辖市、省会城市和自治区首府同时举行。 本次公开遴选和公开选调中央机关共有42个部门参加，计划选拔213人。其中，公开遴选职位包括副处长职务和一级调研员及以下职级，计划选拔197人；公开选调职位为一级至四级调研员职级…"
