    "content": "近日，中共中央政治局常委、中央巡视工作领导小组组长李希出席二十届中央第八轮巡视工作动员部署会并讲话。新华社记者 岳月伟 摄 新华社北京10月24日电 中共中央政治局常委、中央巡视工作领导小组组长李希近日出席二十届中央第八轮巡视工作动员部署会并讲话。会议传达学习了习近平总书记听取中央第七轮巡视情况汇报时的重要讲话精神，对巡视教育部和中管高校作出安排，强调要认真学习领会习近平新时代中国特色社会主义思想特别是习近平党建思想，深刻领悟“两个确立”的决定性意义、坚决做到“两个维护”，以更高标准、更实举措推动新征程巡视工作高质…"
