    "author": "",
    "description": "作为今年中国上海国际艺术节的重磅项目，10月23日-28日在上海大歌剧院，捷杰耶夫与马林斯基交响乐团将用6天8场音乐会演完他的15部交响曲。 这套音乐马拉松正在火热进行中。10月24日下午，刚在申厅指挥完一场老肖音乐会，捷杰耶夫便兴冲冲赶到红厅，赶上威尼斯凤凰歌剧院歌剧《托斯卡》第三幕，这场“梦幻联动”也在观众席引起一阵小骚动。 “上海拥有了一座无与伦比的歌剧院，我很荣幸能够参与开幕活动。”捷杰耶夫依然用一根“牙签”掌控全场，为什么偏爱…",
    "content": "作为今年中国上海国际艺术节的重磅项目，10月23日-28日在上海大歌剧院，捷杰耶夫与马林斯基交响乐团将用6天8场音乐会演完他的15部交响曲。 这套音乐马拉松正在火热进行中。10月24日下午，刚在申厅指挥完一场老肖音乐会，捷杰耶夫便兴冲冲赶到红厅，赶上威尼斯凤凰歌剧院歌剧《托斯卡》第三幕，这场“梦幻联动”也在观众席引起一阵小骚动。 “上海拥有了一座无与伦比的歌剧院，我很荣幸能够参与开幕活动。”捷杰耶夫依然用一根“牙签”掌控全场，为什么偏爱“牙签”指挥棒？他笑说，“我周围全是演奏家，我不想拿粗大的指挥棒挡在他们眼前。”…"
