    "title": "每周航班约11.6万班 全国民航将换季运行",
    "link": "http://www.news.cn/20261024/a0bd1eb1296c4c16a73244c3f0c4eadc/c.html",
    "pub_date": "2026-10-24 18:30:21",
    "author": "",
    "description": "新华社北京10月24日电（记者王聿昊）记者24日从中国民航局获悉，全国民航将于2026年10月25日至2027年3月27日执行2026/2027年冬春航季航班计划。216家国内外航空公司计划在新航季每周安排客货运航班约11.6万班。 国内航班方面，61家航空公司计划每周安排国内航班约9.4万班，其中客运航班每周91454班，货运航班每周2812班。34家航空公司计划在新航季新开288条国内航线，主要集中在西北、东北、西南地区与华东、中南…",
    "content": "新华社北京10月24日电（记者王聿昊）记者24日从中国民航局获悉，全国民航将于2026年10月25日至2027年3月27日执行2026/2027年冬春航季航班计划。216家国内外航空公司计划在新航季每周安排客货运航班约11.6万班。 国内航班方面，61家航空公司计划每周安排国内航班约9.4万班，其中客运航班每周91454班，货运航班每周2812班。34家航空公司计划在新航季新开288条国内航线，主要集中在西北、东北、西南地区与华东、中南地区之间的干支衔接航线上，推动跨区域、多层级航空网络不断完善。 国际航班方面，1…"
