    "content": "新华社北京10月24日电 中央广播电视总台纪念中国工农红军长征胜利90周年主题音像出版物，24日起向海内外公开发行。出版物包括60集电视剧《伟大的长征》、电视文艺晚会《长征颂歌》、7集纪录片《伟大远征》以及12集纪录片《万水千山》。 60集电视剧《伟大的长征》全景展现中央红军及多路红军历经艰难困苦赢得长征胜利的辉煌史实，全方位、多层次、立体化呈现长征这一人类历史壮举。电视文艺晚会《长征颂歌》融汇音乐舞蹈、电影艺术、戏剧曲艺等表演形式，打造了长征题材的“电视艺术史诗”。 7集纪录片《伟大远征》集中展示人民军队听党指挥…"
