    "description": "中共江西省委副书记陈永奇履新江西省政府党组书记。 据《江西日报》星期六（10月24日）报道，江西省委决定，陈永奇任江西省政府党组书记。 公开资料显示，现年58岁的陈永奇曾在山西工作多年，历任山西省政府秘书长，阳泉市市长，阳泉市委书记，山西省副省长等职。 2019年1月，他调任西藏自治区党委常委、组织部部长，2021年10月任西藏自治区党委副书记、自治区政府党组副书记、常务副主席。 此前担任江西省委副书记、省长、省政府党组书记的叶建春，今…",
    "content": "中共江西省委副书记陈永奇履新江西省政府党组书记。 据《江西日报》星期六（10月24日）报道，江西省委决定，陈永奇任江西省政府党组书记。 公开资料显示，现年58岁的陈永奇曾在山西工作多年，历任山西省政府秘书长，阳泉市市长，阳泉市委书记，山西省副省长等职。 2019年1月，他调任西藏自治区党委常委、组织部部长，2021年10月任西藏自治区党委副书记、自治区政府党组副书记、常务副主席。 此前担任江西省委副书记、省长、省政府党组书记的叶建春，今年8月27日被通报接受调查。中共中央纪委国家监委当时通报，叶建春涉嫌严重违纪违法…"
