    "content": "中国官方公布，中共中央宣传部副部长、中国国务院新闻办公室主任莫高义获任云南省委书记。 据新华社星期六（10月24日）发布的消息，中共中央日前决定，莫高义任云南省委委员、常委、书记，王宁不再担任云南省委书记、常委、委员职务。 公开简历显示，现年62岁的莫高义是湖北石首人，拥有历史学博士学位。他长期在广东省宣传系统任职，历任省委外宣办副主任科员、主任科员，省委外宣办（省新闻办）副主任（正处级）、常务副主任（副厅级）等职。 2010年9月，莫高义任广东省委宣传部副部长兼省委外宣办（省新闻办）主任，之后任南方报业传媒集团党…"
